en.css:
.paper.fm-en,.paper.fm-en{margin: 0; padding: 0;}
.paper.fm-en{font-family: "MtcSans", "MtcKr", sans-serif; color: #000;}
.paper.fm-en .page{position: relative;
  width: 297mm;
  height: 210mm;
  overflow: hidden;
  page-break-after: always;}
.paper.fm-en .page:last-child{page-break-after: auto;}
.paper.fm-en .a{position: absolute;}
.paper.fm-en .f7{font-size: 7pt; letter-spacing: -0.06em;}
.paper.fm-en .f8{font-size: 8pt; letter-spacing: -0.06em;}
.paper.fm-en .nls{letter-spacing: 0;}
.paper.fm-en .f9{font-size: 9pt; letter-spacing: -0.06em;}
.paper.fm-en .f16{font-size: 16pt; letter-spacing: -0.06em;}
.paper.fm-en .kr{font-family: "MtcKr", sans-serif;}
.paper.fm-en .c{text-align: center;}
.paper.fm-en .r{text-align: right;}
.paper.fm-en .ml{white-space: pre-line;}
.paper.fm-en .nw{white-space: nowrap; overflow: hidden;}
.paper.fm-en .sm{font-size: 9pt;}
.paper.fm-en .ln{height: 3.2mm; line-height: 3.2mm;}
.paper.fm-en .box{border: 0.18mm solid #000;}
.paper.fm-en .line-h{border-top: 0.18mm solid #000;}
.paper.fm-en .line-v{border-left: 0.18mm solid #000;}
.paper.fm-en .img{position: absolute;}
.paper.fm-en .img img{display: block;}
.paper.fm-en table.grid{border-collapse: collapse;
  table-layout: fixed;
  font-family: "MtcSans80", "MtcKr80", "MtcSans", "MtcKr", sans-serif;
  font-size: 8pt;}
.paper.fm-en table.grid td,.paper.fm-en table.grid th{border: 0.18mm solid #000;
  padding: 0;
  text-align: center;
  vertical-align: middle;
  overflow: hidden;
  word-wrap: break-word;}
.paper.fm-en table.grid thead th{font-size: 6pt; line-height: 1.08; font-weight: normal; letter-spacing: -0.048em;}
.paper.fm-en table.grid thead tr.gap td{height: 1mm; border-left: none; border-right: none;}
.paper.fm-en table.grid tbody td{height: 9mm; font-size: 8pt; line-height: 1.2; white-space: pre-line; vertical-align: top;}
.paper.fm-en table.grid td.left{text-align: left; padding-left: 0.6mm;}
.paper.fm-en table.grid td.r{text-align: right; padding-right: 0.6mm;}
.paper.fm-en table.grid tr.total td{height: 5.647mm; font-size: 7pt; vertical-align: middle; background: #e1e1e1;}
.paper.fm-en table.grid th.vert{overflow: visible; vertical-align: top;}
.paper.fm-en th.vert .vbox{position: relative;}
.paper.fm-en th.vert .vbox span{position: absolute;
  display: block;
  text-align: center;
  white-space: nowrap;
  line-height: 1.45mm;   
  transform: rotate(-90deg);}
.paper.fm-en table.color{border-collapse: collapse; table-layout: fixed; font-size: 7pt; letter-spacing: -0.06em;}
.paper.fm-en table.color td{height: 4mm; padding: 0 0.5mm; vertical-align: middle; white-space: nowrap; overflow: hidden;}

